func (r *UserRepository) TransferCredits(ctx context.Context, fromID, toID string, amount int) error {
    tx, err := r.db.Begin()
    if err != nil {
        return fmt.Errorf("begin tx: %w", err)
    }
    defer tx.Rollback()

    _, err = tx.ExecContext(ctx, "UPDATE users SET credits = credits - $1 WHERE id = $2", amount, fromID)
    if err != nil {
        return fmt.Errorf("debit: %w", err)
    }

    _, err = tx.ExecContext(ctx, "UPDATE users SET credits = credits + $1 WHERE id = $2", amount, toID)
    if err != nil {
        return fmt.Errorf("credit: %w", err)
    }

    return tx.Commit()
}
```

What is wrong with how context is used? Fix it.
